"""Native compile of the selected kernels as generated by the current P4 base."""
import importlib.util,hashlib,json,subprocess,sysconfig,re
from pathlib import Path
from torch.utils import cpp_extension
H=Path(__file__).resolve().parent
sp=importlib.util.spec_from_file_location('sgq_layer_compile',H/'layer_qkv_candidate.py');m=importlib.util.module_from_spec(sp);sp.loader.exec_module(m)
ns,insts,plans=m.sgq_source(False,m.SGQ_SELECTED);source=ns['v18s_cuda_source'](insts)
folder=H/'native';folder.mkdir(exist_ok=True);p=folder/'layer_qkv.cu';p.write_text(source)
flags=['-O3','-std=c++20','-gencode=arch=compute_90a,code=sm_90a','-DTORCH_EXTENSION_NAME=sgq_compile','-DTORCH_API_INCLUDE_EXTENSION_H','-Xptxas=-v','-isystem',sysconfig.get_paths()['include']]
flags += [a for path in cpp_extension.include_paths(device_type='cuda') for a in ('-isystem',path)]
run=subprocess.run(['nvcc',*flags,'-c',str(p),'-o',str(p.with_suffix('.o'))],capture_output=True,text=True);log=run.stdout+run.stderr;p.with_suffix('.log').write_text(log);assert run.returncode==0,log[-3000:]
spills=re.findall(r'(\d+) bytes stack frame, (\d+) bytes spill stores, (\d+) bytes spill loads',log)
assert all(set(v)=={'0'} for v in spills)
out=dict(passed=True,candidate_sha256=hashlib.sha256((H/'layer_qkv_candidate.py').read_bytes()).hexdigest(),source_sha256=hashlib.sha256(source.encode()).hexdigest(),units=len(insts),plans=sorted([*key] for key in plans),registers=list(map(int,re.findall(r'Used (\d+) registers',log))),stack_spills=spills)
(H/'layer_qkv_native.json').write_text(json.dumps(out,indent=2)+'\n');print(out)
